  ctx.fill();
  ctx.strokeStyle = rim;
  ctx.lineWidth = Math.max(1.8, 0.036 * H);
  ctx.stroke();
  ellipse(ctx, 0.1 * H, 0.13 * H, 0.17 * H, 0.31 * H, 0.04);
  ctx.fillStyle = white;
  ctx.fill();
  ellipse(ctx, 0.11 * H, -0.3 * H, 0.105 * H, 0.1 * H);
  ctx.fillStyle = white;
  ctx.fill();
