      o.y = lerp(yS, yW + 0.05 * H, u * u);
      o.rot = lerp(Math.PI / 2 + tt(xb), Math.PI / 2 + 0.85, ss(0, 1, u));
      o.fa = 1.1;
      o.pa = 1;
      o.rp = o.rot - Math.PI / 2;
