      o.x = lerp(xe0, xe1, ss(0, 1, u));
      o.y = lerp(yW + 0.05 * H, yW + 0.44 * H, Math.sin(u * Math.PI / 2));
      o.rot = lerp(Math.PI / 2 + 0.85, Math.PI / 2 + 0.2, ss(0, 1, u));
